"""
Demo: enumerate the Bruhat order on S_n and print its Hasse diagram
(covering relations), plus rank statistics per length level.
"""
from __future__ import annotations
from itertools import permutations
from collections import Counter
from typing import List, Tuple

Perm = Tuple[int, ...]

def rk(w: Perm, i: int, j: int) -> int:
    return sum(1 for k in range(i + 1) if w[k] <= j)

def bruhat_le(u: Perm, v: Perm) -> bool:
    n = len(u)
    return all(rk(v, i, j) <= rk(u, i, j) for i in range(n) for j in range(n))

def num_inversions(w: Perm) -> int:
    n = len(w)
    return sum(1 for i in range(n) for j in range(i + 1, n) if w[i] > w[j])

def covers(n: int) -> List[Tuple[Perm, Perm]]:
    """Covering relations u <*> v: comparable with length difference exactly 1."""
    perms = list(permutations(range(n)))
    result: List[Tuple[Perm, Perm]] = []
    for u in perms:
        for v in perms:
            if u != v and bruhat_le(u, v) and \
               num_inversions(v) == num_inversions(u) + 1:
                result.append((u, v))
    return result

def main() -> None:
    n = 3
    print(f"Bruhat order on S_{n}: covering relations u -> v")
    for u, v in covers(n):
        print(f"  {u}  ->  {v}   (len {num_inversions(u)} -> {num_inversions(v)})")
    print("\nLevel sizes by length (rank function of the order):")
    c = Counter(num_inversions(w) for w in permutations(range(n)))
    for length in sorted(c):
        print(f"  length {length}: {c[length]} permutation(s)")

if __name__ == "__main__":
    main()

