from typing import List, Tuple
Perm = Tuple[int, ...]

def rank_matrix(w: Perm) -> List[List[int]]:
    n = len(w)
    matrix: List[List[int]] = []
    seen = [0] * n
    for i in range(n):
        seen[w[i]] = 1
        acc = 0
        row: List[int] = []
        for j in range(n):
            acc += seen[j]
            row.append(acc)
        matrix.append(row)
    return matrix

def bruhat_le(u: Perm, v: Perm) -> bool:
    """Return True iff u <= v in Bruhat order (Ehresmann criterion), O(n^2)."""
    ru, rv = rank_matrix(u), rank_matrix(v)
    n = len(u)
    return all(rv[i][j] <= ru[i][j] for i in range(n) for j in range(n))

def prod_bruhat_le(p: Tuple[Perm, Perm], q: Tuple[Perm, Perm]) -> bool:
    """Componentwise product Bruhat order on pairs of permutations."""
    return bruhat_le(p[0], q[0]) and bruhat_le(p[1], q[1])

