Input: rank matrix M (n x n)
for i = 0 to n-1:
    prev <- M[i-1] if i>0 else all-zeros
    before <- 0
    for j = 0 to n-1:
        ind <- M[i][j] - prev[j]
        if ind == 1 and before == 0:
            w[i] <- j; break
        before <- ind
return w

