"""Draw the Hasse diagram of the Bruhat order on S_n, layered by length."""
from itertools import permutations
from typing import Dict, List, Tuple
import matplotlib.pyplot as plt

Perm = Tuple[int, ...]

def rk(w: Perm, i: int, j: int) -> int:
    return sum(1 for k in range(i + 1) if w[k] <= j)

def bruhat_le(u: Perm, v: Perm) -> bool:
    n = len(u)
    return all(rk(v, i, j) <= rk(u, i, j) for i in range(n) for j in range(n))

def inversions(w: Perm) -> int:
    n = len(w)
    return sum(1 for i in range(n) for j in range(i + 1, n) if w[i] > w[j])

def main() -> None:
    n = 3
    perms = list(permutations(range(n)))
    levels: Dict[int, List[Perm]] = {}
    for w in perms:
        levels.setdefault(inversions(w), []).append(w)
    pos: Dict[Perm, Tuple[float, float]] = {}
    for lvl, ws in levels.items():
        for idx, w in enumerate(sorted(ws)):
            pos[w] = (idx - (len(ws) - 1) / 2, lvl)
    fig, ax = plt.subplots(figsize=(6, 6))
    for u in perms:
        for v in perms:
            if u != v and bruhat_le(u, v) and inversions(v) == inversions(u) + 1:
                x0, y0 = pos[u]; x1, y1 = pos[v]
                ax.plot([x0, x1], [y0, y1], color="gray", zorder=1)
    for w, (x, y) in pos.items():
        ax.scatter([x], [y], s=700, color="lightsteelblue", zorder=2)
        ax.text(x, y, "".join(map(str, w)), ha="center", va="center", zorder=3)
    ax.set_title(f"Bruhat order on S_{n} (Hasse diagram)")
    ax.set_ylabel("length (# inversions)")
    ax.set_xticks([])
    plt.tight_layout()
    plt.savefig("bruhat_hasse.png", dpi=140)
    print("wrote bruhat_hasse.png")

if __name__ == "__main__":
    main()

